async function init(page,{seed=false}={}){
 await page.route('**/cloud.js*',route=>route.abort());
 await page.addInitScript(()=>{window.__elaraPaint=[];const start=performance.now();let frames=0;const sample=()=>{const shell=document.querySelector('.shell'),nav=document.querySelector('.bottom-nav [data-elara-tab="home"] .elara-nav-art, .sidebar [data-elara-tab="home"] .elara-nav-art'),booting=document.documentElement.hasAttribute('data-elara-booting');window.__elaraPaint.push({ms:Math.round(performance.now()-start),booting,shell:shell?getComputedStyle(shell).visibility:'not-mounted',navPresent:!!nav,navReady:!!(nav?.complete&&nav?.naturalWidth),navSrc:nav?.getAttribute('src')||null});if(++frames<300&&(booting||frames<26))requestAnimationFrame(sample)};addEventListener('DOMContentLoaded',()=>requestAnimationFrame(sample),{once:true})});
 if(seed)await page.addInitScript(fixture);
 await page.goto('http://127.0.0.1:4173/#home',{waitUntil:'domcontentloaded',timeout:30000});
 await page.waitForFunction(()=>window.ElaraNavigation&&window.ElaraReferenceHome&&window.ElaraOpen&&!document.documentElement.hasAttribute('data-elara-booting'),null,{timeout:30000});
 await page.waitForFunction(()=>{const x=document.querySelector('.bottom-nav [data-elara-tab="home"] .elara-nav-art, .sidebar [data-elara-tab="home"] .elara-nav-art');return !!x&&x.complete&&x.naturalWidth>0},null,{timeout:15000});
 const first=await page.evaluate(()=>window.__elaraPaint||[]);assert.equal(first.some(x=>x.booting&&x.shell==='visible'),false,'legacy shell painted during boot');const released=first.find(x=>!x.booting);assert.ok(released,'no visible frame sampled');assert.equal(released.navPresent,true,'nav artwork installed after first visible shell frame');
 await page.addStyleTag({content:'#cloud-layer{display:none!important}body:not(.cloud-ready) .shell,body.cloud-locked .shell,body:not(.cloud-ready) .bottom-nav{visibility:visible!important}*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}'});
 await page.evaluate(()=>{document.body.classList.add('cloud-ready');document.body.classList.remove('cloud-locked');document.getElementById('cloud-layer')?.setAttribute('hidden','');window.ElaraNavigation.render();window.ElaraReferenceHome.render();window.ElaraOpen('home',{history:'replace'})});
 await page.waitForTimeout(350);
 if(seed){await page.evaluate(()=>localStorage.removeItem('elara-test-seeded'));await page.evaluate(fixture);await page.evaluate(()=>window.dispatchEvent(new CustomEvent('elara:hydrate',{detail:JSON.parse(localStorage.getItem('elara_space_v1'))})));await page.evaluate(()=>window.ElaraReferenceHome.render());await page.waitForTimeout(170)}
 return first;
}
const rect=(page,sel)=>page.locator(sel).first().evaluate(el=>{const r=el.getBoundingClientRect();return {x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)}});
const delta=(a,b)=>({top:Math.abs(a.y-b.y),width:Math.abs(a.w-b.w),height:Math.abs(a.h-b.h)});
async function stabilityProbe(page,selector,label,width){
 const roots={ranking:'.ref-ranks',friends:'.ref-activity'},before={};
 const docRect=async sel=>page.locator(sel).first().evaluate(el=>{const r=el.getBoundingClientRect();return{x:Math.round(r.x+scrollX),y:Math.round(r.y+scrollY),w:Math.round(r.width),h:Math.round(r.height)}});
 for(const [name,sel] of Object.entries(roots)){const el=page.locator('#panel-home '+sel);await el.evaluate((node,id)=>node.dataset.stabilityProbe=id,name+'-'+width);before[name]=await docRect('#panel-home '+sel)}
 const control=page.locator(selector).first(),initial=await control.getAttribute('aria-pressed'),samples=[];
 for(let i=0;i<3;i++){
  await control.click();await page.waitForTimeout(110);
  const sample={};
  for(const [name,sel] of Object.entries(roots)){
   const el=page.locator('#panel-home '+sel),box=await docRect('#panel-home '+sel),d=delta(before[name],box);
   assert.equal(await el.getAttribute('data-stability-probe'),name+'-'+width,label+' destroyed/recreated '+name+' DOM at '+width);
   assert.ok(d.top<=2&&d.width<=2&&d.height<=2,label+' shifted '+name+' geometry at '+width+': '+JSON.stringify(d));
   assert.equal(await el.isVisible(),true,label+' caused visible '+name+' flicker at '+width);sample[name]={box,d};
  }
  samples.push(sample);
 }
 if((await control.getAttribute('aria-pressed'))!==initial){await control.click();await page.waitForTimeout(110)}
 return {before,samples};
}
async function assertCircle(locator,label){
 const rows=await locator.evaluateAll(nodes=>nodes.map(el=>{const r=el.getBoundingClientRect();return {w:r.width,h:r.height,ratio:getComputedStyle(el).aspectRatio,radius:getComputedStyle(el).borderRadius}}));
 assert.ok(rows.length>0,label+' controls missing');
 for(const row of rows)assert.ok(Math.abs(row.w-row.h)<=1,label+' is not circular: '+JSON.stringify(row));
 return rows;
}
async function assertCheckedFill(page,controlSelector,label){
 const control=page.locator(controlSelector).first(),initial=await control.getAttribute('aria-pressed');
 if(initial!=='true'){await control.click();await page.waitForTimeout(110)}
 const img=control.locator('img').first();assert.equal(await img.count(),1,label+' checked artwork missing');
 assert.ok((await img.getAttribute('src'))?.includes('Glowing Neon Checkmark Orb.webp'),label+' uses wrong checked artwork');
 const fit=await control.evaluate(el=>{const p=el.getBoundingClientRect(),c=el.querySelector('img')?.getBoundingClientRect(),cs=getComputedStyle(el),is=getComputedStyle(el.querySelector('img'));return {dw:c?Math.abs(p.width-c.width):99,dh:c?Math.abs(p.height-c.height):99,w:p.width,h:p.height,fit:is.objectFit,ratio:cs.aspectRatio}});
 assert.ok(Math.abs(fit.w-fit.h)<=1&&fit.dw<=1&&fit.dh<=1,label+' artwork does not fill a true circle: '+JSON.stringify(fit));
 if(initial!=='true'){await control.click();await page.waitForTimeout(110)}
 return fit;
}
async function assertInternalScroll(page,bodySelector,label){
 const body=page.locator(bodySelector).first();assert.equal(await body.count(),1,label+' body missing');
 const result=await body.evaluate(el=>{const card=el.closest('.ref-card'),before=card.getBoundingClientRect(),style=getComputedStyle(el),probes=[];for(let i=0;i<20;i++){const p=document.createElement('div');p.dataset.scrollProbe='1';p.style.cssText='height:28px;min-height:28px;flex:0 0 28px;pointer-events:none';el.append(p);probes.push(p)}const after=card.getBoundingClientRect(),client=el.clientHeight,scroll=el.scrollHeight;el.scrollTop=Math.min(80,Math.max(1,scroll-client));const moved=el.scrollTop;for(const p of probes)p.remove();el.scrollTop=0;return{overflow:style.overflowY,touch:style.touchAction,client,scroll,moved,before:{x:before.x,y:before.y,w:before.width,h:before.height},after:{x:after.x,y:after.y,w:after.width,h:after.height}}});
 assert.ok(result.overflow==='auto'||result.overflow==='scroll',label+' is not internally scrollable: '+result.overflow);
 assert.ok(result.scroll>result.client&&result.moved>0,label+' body did not scroll after growth');
 const d=delta({x:result.before.x,y:result.before.y,w:result.before.w,h:result.before.h},{x:result.after.x,y:result.after.y,w:result.after.w,h:result.after.h});
 assert.ok(d.top<=2&&d.width<=2&&d.height<=2,label+' growth changed card geometry: '+JSON.stringify(d));
 return result;
}
async function firstPaintReload(page,mode){if(mode==='hard'){const cdp=await page.context().newCDPSession(page);await cdp.send('Network.setCacheDisabled',{cacheDisabled:true});await page.reload({waitUntil:'domcontentloaded'});await page.waitForFunction(()=>!document.documentElement.hasAttribute('data-elara-booting'));await cdp.send('Network.setCacheDisabled',{cacheDisabled:false});await cdp.detach()}else{await page.reload({waitUntil:'domcontentloaded'});await page.waitForFunction(()=>!document.documentElement.hasAttribute('data-elara-booting'))}return page.evaluate(()=>({shell:getComputedStyle(document.querySelector('.shell')).visibility,navSrc:document.querySelector('.bottom-nav [data-elara-tab="home"] .elara-nav-art, .sidebar [data-elara-tab="home"] .elara-nav-art')?.getAttribute('src'),paint:window.__elaraPaint||[]}))}

async function bootTriptych(width,height){
 const page=await browser.newPage({viewport:{width,height},deviceScaleFactor:1,hasTouch:width<=700});
 await page.route('**/cloud.js*',route=>route.abort());
 await page.route('**/assets/ui/*.webp',async route=>{await new Promise(r=>setTimeout(r,220));await route.continue()});
 await page.goto('http://127.0.0.1:4173/#home',{waitUntil:'commit',timeout:30000});
 await page.waitForFunction(()=>document.documentElement?.hasAttribute('data-elara-booting'),null,{timeout:3000});
 await page.waitForTimeout(70);
 const before=await page.evaluate(()=>{const visible=el=>{if(!el)return false;const s=getComputedStyle(el),r=el.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&s.opacity!=='0'&&r.width>0&&r.height>0};return {boot:visible(document.querySelector('#elara-boot-screen')),shell:visible(document.querySelector('.shell')),bottom:visible(document.querySelector('.bottom-nav')),dock:visible(document.querySelector('.elara-desktop-dock')),routes:[...document.querySelectorAll('.bottom-nav [data-elara-tab]')].map(x=>x.dataset.elaraTab)}});
 assert.equal(before.boot,true,'boot screen must be the only first-frame shell');
 assert.equal(before.shell,false,'app shell leaked during boot');
 assert.equal(before.bottom,false,'bottom navigation leaked during boot');
 assert.equal(before.dock,false,'desktop dock leaked during boot');
 if(width<=700)assert.deepEqual(before.routes,mobile,'mobile nav DOM routes incomplete during boot');
 await page.screenshot({path:`${out}/boot-${width}-before-release.png`,fullPage:false});
 await page.waitForFunction(()=>!document.documentElement.hasAttribute('data-elara-booting'),null,{timeout:5000});
 const releaseState=await page.evaluate(()=>{const nav=[...document.querySelectorAll('.bottom-nav .elara-nav-art,.sidebar .elara-nav-art')].filter(x=>x.getClientRects().length>0);const moon=document.querySelector('#theme-toggle .ref-theme-art'),src=moon?.getAttribute('src')||'',boot=document.querySelector('#elara-boot-screen');return {bootVisible:!!boot&&getComputedStyle(boot).display!=='none',artReady:nav.length>0&&nav.every(x=>x.complete&&x.naturalWidth>0)&&!!moon&&moon.getClientRects().length>0&&moon.complete&&moon.naturalWidth>0&&/(icon-mode-night-(active|default)\.webp)$/.test(src)}});
 assert.equal(releaseState.bootVisible,false,'boot screen did not clear at shell release');
 assert.equal(releaseState.artReady,true,'navigation/Moon artwork was not decoded at shell release');
 await page.screenshot({path:`${out}/boot-${width}-release.png`,fullPage:false});await page.waitForTimeout(500);await page.screenshot({path:`${out}/boot-${width}-plus500ms.png`,fullPage:false});
 await page.close();
}
